 "content": "def transform(grid):
    """Fill the interior of each hollow rectangular frame by interior parity."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            # Gather 4-connected component of a non-background color.
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            # A rectangular frame consists of the entire bounding-box perimeter.
            perimeter = {(y,x) for y in range(top,bottom+1) for x in range(left,right+1)
                         if y in (top,bottom) or x in (left,right)}
            if (bottom-top >= 2 and right-left >= 2 and set(cells) == perimeter):
                fill = 7 if (bottom-top-1) % 2 == 1 else 2
                for y in range(top+1,bottom):
                    for x in range(left+1,right):
                        out[y][x] = fill
    return out
